      "topic": "R-CNN architecture",
      "difficulty": "medium",
      "question": "Tại sao Fast R-CNN (2015) được coi là cải tiến hơn so với R-CNN (2014) về mặt hiệu năng?",
      "options": [
        {
          "id": "A",
          "text": "Nó sử dụng nhiều vùng đề xuất hơn để tăng độ chính xác."
        },
        {
          "id": "B",
          "text": "Nó chia sẻ tính toán CNN cho toàn bộ ảnh thay vì chạy riêng lẻ cho từng vùng."
        },
        {
          "id": "C",
          "text": "Nó loại bỏ hoàn toàn việc sử dụng các vùng đề xuất (region proposals)."
        },
        {
          "id": "D",
          "text": "Nó tăng số lượng vùng đề xuất lên gấp đôi so với R-CNN."
        }
      ],
      "correct_option_id": "B",
      "explanation": "Fast R-CNN nhanh hơn vì nó chia sẻ tính toán CNN cho toàn bộ ảnh thay vì chạy CNN riêng lẻ cho từng vùng như R-CNN.",
      "citation": {
        "source_id": "Computer_Vision_Bai_Giang.pptx#Slide49",
        "parent_source_id": "Computer_Vision_Bai_Giang.pptx#Slide49",
        "quote": "Họ mô hình R-CNN. R-CNN (2014) trích xuất ~2000 vùng đề xuất (region proposals) và chạy CNN riêng lẻ. Fast R-CNN (2015) chia sẻ tính toán CNN cho toàn bộ ảnh, nhanh hơn nhiều."
      }
    }
  ]
}

